    const menu=document.createElement('div');menu.dataset.instant=String(instant);menu.className='glass-menu';menu.id='glassMenu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',select.getAttribute('aria-label')||'选择');
    menu.innerHTML=[...select.options].map((o,i)=>'<button type="button" role="option" tabindex="-1" data-option="'+i+'" '+(o.disabled?'disabled':'')+' aria-selected="'+o.selected+'"><span>'+escape(o.textContent)+'</span><svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg></button>').join('');const scroller=document.createElement('div');scroller.className='glass-menu-scroll';while(menu.firstChild)scroller.append(menu.firstChild);menu.append(scroller);scroller.style.maxHeight=(Math.min(300,innerHeight-28)-14)+'px';document.body.append(menu);trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls',menu.id);
    const rect=trigger.getBoundingClientRect(),width=Math.min(innerWidth-20,Math.max(rect.width,152));menu.style.width=width+'px';menu.style.left=Math.min(innerWidth-width-10,Math.max(10,rect.left))+'px';menu.style.maxHeight=Math.min(300,innerHeight-28)+'px';
    const height=Math.min(menu.scrollHeight,300,innerHeight-28),below=rect.bottom+height+12<innerHeight;menu.style.top=(below?rect.bottom+7:Math.max(10,rect.top-height-7))+'px';menu.dataset.placement=below?'bottom':'top';menu.style.setProperty('--menu-origin',Math.min(width,Math.max(0,rect.left+rect.width/2-parseFloat(menu.style.left)))+'px '+(below?'0%':'100%'));menu.style.setProperty('--menu-shift',below?'-4px':'4px');
