      wrap.onpointerenter=()=>{cancelTimers();hoverTimer=setTimeout(()=>open(select,trigger),active?0:110)};wrap.onpointerleave=e=>{clearTimeout(hoverTimer);if(!active?.menu.contains(e.relatedTarget))leave(select)};select.addEventListener('change',()=>sync(select));
